mapper.select:
SELECT public_data_sync_item_id AS publicDataSyncItemId, source_name AS sourceName, item_type AS itemType, external_id AS externalId, title, description, provider_url AS providerUrl, display_year AS displayYear, creator_name AS creatorName, raw_json AS rawJson, synced_at AS syncedAt FROM public_data_sync_item WHERE active_yn = 'Y'
AND item_type = #{itemType}
AND ( title LIKE CONCAT('%', #{keyword}, '%') OR creator_name LIKE CONCAT('%', #{keyword}, '%') OR external_id LIKE CONCAT('%', #{keyword}, '%') OR source_name LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY synced_at DESC, public_data_sync_item_id DESC LIMIT #{limit}
